BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Completeness of information representation
(1, 'Written Representations', 'During the audit of Cascade Ventures for the year ended December 31, 2025, the engagement team at Sterling & Associates prepares the representation letter. Management has provided all requested financial records but questions whether they must also represent that all transactions have been recorded. Under AU-C 580, the completeness representation requires management to confirm that:', '["All transactions have been recorded and are reflected in the financial statements", "Only material transactions have been identified and disclosed to the auditor", "Transactions were recorded in compliance with tax regulations", "Financial records are free from any computational errors"]'::jsonb, 0, 'AU-C 580.A11 requires a completeness representation confirming that all transactions have been recorded and reflected in the financial statements. This encompasses the complete population of transactions, not just material ones. Unlike choice B, which limits the scope to material transactions, the completeness assertion covers all transactions regardless of individual materiality.', 'medium', 3),

-- Q2: medium / L3 — Uncorrected misstatements aggregate acknowledgment
(1, 'Written Representations', 'Whitmore Industries has three uncorrected misstatements totaling $42,000 identified during its December 31, 2025 audit by Fletcher & Grant CPA. The engagement partner prepares the representation letter and includes a schedule of uncorrected misstatements. Under AU-C 580, management must represent in writing that:', '["All misstatements have been corrected prior to the issuance of the financial statements", "The effects of uncorrected misstatements are immaterial, both individually and in the aggregate", "The auditor bears responsibility for any uncorrected misstatements not detected during fieldwork", "Uncorrected misstatements will be adjusted in the subsequent reporting period"]'::jsonb, 1, 'AU-C 580.11 requires management to represent that the effects of uncorrected misstatements are immaterial, both individually and in the aggregate, to the financial statements as a whole. The representation acknowledges that management has considered the attached schedule. Unlike choice A, management is not required to correct all misstatements — only to acknowledge their immateriality.', 'medium', 3),

-- Q3: easy / L1 — Definition of written representations
(1, 'Written Representations', 'What are written representations in the context of an audit engagement?', '["Oral statements made by management during exit conferences", "Third-party confirmations obtained by the auditor from banks", "Written statements provided by management to the auditor to confirm certain matters or to support other audit evidence", "Engagement letters signed before the audit begins"]'::jsonb, 2, 'AU-C 580.07 defines written representations as written statements by management provided to the auditor to confirm certain matters or to support other audit evidence. They are a required form of audit evidence obtained near the end of the engagement. Unlike choice B, which describes external confirmations from third parties, written representations come directly from management.', 'easy', 1),

-- Q4: medium / L2 — Internal control responsibility representation
(1, 'Written Representations', 'During the wrap-up of the 2025 audit of Greenfield Manufacturing, the engagement partner at Monroe & Associates drafts the management representation letter. The CFO asks why the letter includes a statement about internal controls when the audit is not an integrated audit. Under AU-C 580, management must acknowledge responsibility for:', '["Designing controls that eliminate all possibilities of fraud", "Maintaining controls that satisfy PCAOB inspection standards", "Implementing controls recommended by the prior-year auditor", "Designing, implementing, and maintaining internal control relevant to the preparation of financial statements"]'::jsonb, 3, 'AU-C 580.10 requires management to represent its responsibility for the design, implementation, and maintenance of internal control relevant to the preparation and fair presentation of financial statements. This applies to all audits, not just integrated audits. Unlike choice A, the standard requires controls relevant to financial reporting, not the elimination of all fraud.', 'medium', 2),

-- Q5: easy / L1 — Form of the representation letter
(1, 'Written Representations', 'What form must management representations take under AU-C 580?', '["A written letter addressed to the auditor", "An oral statement recorded in the audit workpapers", "A verbal confirmation during the closing meeting", "An email summary from any member of the accounting department"]'::jsonb, 0, 'AU-C 580.09 specifies that management representations must be in the form of a written representation letter addressed to the auditor. Oral representations alone are insufficient; the standard explicitly requires written form to document management''s assertions. Unlike choice B, oral statements — even if documented by the auditor — do not satisfy the written representation requirement.', 'easy', 1),

-- Q6: hard / L4 — Contradictory evidence vs. written representations
(1, 'Written Representations', 'During the 2025 audit of Ironclad Systems, the engagement partner at Pemberton & Lake obtains management''s written representation that all related-party transactions have been disclosed. However, while testing journal entries, the audit team discovers a $1.8 million payment to an entity owned by the CEO''s spouse that was not disclosed. The engagement partner must evaluate the implications of this contradictory evidence. The most appropriate course of action is to:', '["Reconsider the reliability of all management representations and evaluate the effect on the audit", "Accept the written representation as sufficient because it was provided in good faith", "Issue the audit report with an emphasis-of-matter paragraph noting the discrepancy", "Withdraw the written representation requirement for this specific assertion"]'::jsonb, 0, 'AU-C 580.A27 states that when contradictory evidence exists regarding a written representation, the auditor should investigate the circumstances and reconsider the reliability of other representations made by management. Discovering an undisclosed $1.8 million related-party transaction directly contradicts the completeness representation. Unlike choice B, the auditor cannot accept representations at face value when contradictory audit evidence exists.', 'hard', 4),

-- Q7: medium / L2 — Compliance with laws/regulations representation
(1, 'Written Representations', 'Evergreen Healthcare''s December 31, 2025 audit is being conducted by Crawford & Wells CPA. The engagement partner includes a representation about compliance with laws and regulations in the management representation letter. The CFO questions which laws are covered by this representation. Under AU-C 580, the compliance representation generally covers:', '["All federal, state, and local laws regardless of their connection to the financial statements", "Laws and regulations whose effects should be considered when preparing the financial statements", "Only tax laws and SEC reporting requirements", "Laws specifically identified by the auditor during the planning phase"]'::jsonb, 1, 'AU-C 580.11 requires management to represent compliance with provisions of laws and regulations whose effects should be considered when preparing financial statements. The representation focuses on laws with a direct effect on financial statement amounts and disclosures. Unlike choice A, the representation does not extend to all laws — it targets those relevant to financial reporting.', 'medium', 2),

-- Q8: medium / L3 — Representations about accounting estimates
(1, 'Written Representations', 'The audit team at Blackwell & Moore is finalizing the December 31, 2025 audit of Apex Consulting Group. Apex has significant accounting estimates, including a $3.2 million allowance for doubtful accounts. The engagement partner ensures the representation letter addresses management''s responsibilities for estimates. Under AU-C 580, the representation about accounting estimates should confirm that:', '["The auditor has independently verified and approved all significant estimates", "Estimates were calculated using only observable market data", "The assumptions and methods used in developing accounting estimates are reasonable in the circumstances", "All estimates will be trued up in the subsequent reporting period"]'::jsonb, 2, 'AU-C 580.11 requires management to represent that the methods, significant assumptions, and data used in making accounting estimates are reasonable in the context of the applicable financial reporting framework. This covers all three components of estimates. Unlike choice B, management is not limited to observable data — judgment-based assumptions are permitted but must be reasonable.', 'medium', 3),

-- Q9: medium / L2 — Representations about access to records and personnel
(1, 'Written Representations', 'During the 2025 audit of Pinnacle Distributors, the audit manager at Hoffman & Clarke CPA prepares the draft representation letter. The CFO asks why the letter includes a statement about providing the auditor access to all information. Under AU-C 580, management must represent that it has provided the auditor with:', '["Only information specifically requested through formal written inquiries", "Access to records that management considers relevant to the audit", "Summaries of all accounting transactions for the audit period", "Access to all information that management is aware is relevant to the preparation of the financial statements"]'::jsonb, 3, 'AU-C 580.10-11 requires management to represent that it has provided the auditor with access to all information of which management is aware that is relevant to the preparation and fair presentation of the financial statements. This is broad and affirmative. Unlike choice A, the obligation is not limited to specifically requested items — management must proactively disclose all relevant information.', 'medium', 2),

-- Q10: hard / L4 — Evaluating whether to accept limited representations on contingent liabilities
(1, 'Written Representations', 'Pacific Northwest Airlines is undergoing its December 31, 2025 audit by Kirkland & Frost CPA. During the representation letter process, the CEO agrees to sign all representations except the one about completeness of contingent liabilities, stating that ongoing antitrust litigation makes such a representation impossible. The engagement partner must evaluate the appropriate response. Given that this is a required representation, the auditor should:', '["Accept the limitation and issue a qualified opinion for scope limitation", "Modify the representation to exclude antitrust matters and proceed with an unmodified opinion", "Obtain the CEO''s oral representation instead and document it in the workpapers", "Discuss the matter with management, and if the representation remains unavailable, consider the effect on the ability to form an opinion"]'::jsonb, 3, 'AU-C 580.19-20 states that if management does not provide one or more requested written representations, the auditor should discuss the matter, reevaluate management''s integrity, and determine the effect on the audit opinion — potentially disclaiming. Unlike choice A, the standard does not automatically result in a qualified opinion; the auditor must consider whether a disclaimer is more appropriate given the fundamental nature of the representation.', 'hard', 4),

-- Q11: hard / L4 — Group audit representation letter considerations
(1, 'Written Representations', 'Bennett & Associates serves as the group engagement partner for the consolidated financial statements of Global Dynamics Corp. for the year ended December 31, 2025. Global Dynamics has three significant components audited by other firms. The group engagement partner considers whether written representations from component management are necessary. Under AU-C 600, when the group engagement partner uses the work of component auditors, the group engagement partner should:', '["Rely solely on the component auditors'' representation letters without obtaining group-level representations", "Obtain written representations from group management, including matters relevant to the consolidated financial statements", "Require each component auditor to forward their representation letters for the group audit file", "Waive the representation letter requirement because component audits provide sufficient evidence"]'::jsonb, 1, 'AU-C 600.40 requires the group engagement partner to obtain written representations from group management on matters relevant to the group financial statements, including the completeness of information provided about components. Unlike choice A, the group engagement partner cannot rely solely on component-level representation letters — group management must separately represent matters at the consolidated level.', 'hard', 4),

-- Q12: hard / L3 — Going concern representations
(1, 'Written Representations', 'During the December 31, 2025 audit of Northstar Fabrication, the engagement team at Langley & Park identifies conditions that raise substantial doubt about the entity''s ability to continue as a going concern. Management believes the company will survive and has prepared a remediation plan. The engagement partner drafts the representation letter to address going concern. Under AU-C 580, the representation letter should include management''s statement that:', '["The auditor has evaluated and approved management''s going concern remediation plan", "Substantial doubt about going concern has been eliminated by management''s corrective actions", "Management''s plans to mitigate the going concern conditions have been disclosed to the auditor", "The entity will continue operations for at least 24 months beyond the balance sheet date"]'::jsonb, 2, 'AU-C 580.11 and AU-C 570 require the representation letter to include management''s disclosure of plans intended to mitigate going concern doubts. Management represents that it has communicated its plans and relevant information to the auditor. Unlike choice B, the representation does not require management to assert that substantial doubt has been eliminated — only that plans and relevant information have been disclosed.', 'hard', 3),

-- Q13: medium / L2 — Additional entity-specific representations
(1, 'Written Representations', 'The audit team at Wallace & Burton CPA is conducting the December 31, 2025 audit of Redwood Pharmaceuticals, which recently completed an FDA regulatory submission. The engagement partner considers whether the standard representation letter is sufficient. Under AU-C 580, when should the auditor request additional written representations beyond the standard required ones?', '["Only when the audit committee specifically requests additional representations", "Only when the entity has received a going concern opinion in the prior year", "Only when the engagement is a first-year audit and the predecessor auditor requires them", "When the auditor considers it necessary to support other audit evidence relevant to the financial statements"]'::jsonb, 3, 'AU-C 580.13 permits the auditor to request additional written representations about the financial statements when deemed necessary to support other audit evidence. Entity-specific matters — such as regulatory compliance or pending approvals — may warrant supplemental representations. Unlike choice A, the decision to request additional representations rests with the auditor, not the audit committee.', 'medium', 2),

-- Q14: easy / L1 — Addressee of the representation letter
(1, 'Written Representations', 'To whom is the management representation letter typically addressed?', '["The auditor or the audit firm", "The entity''s board of directors", "The SEC or applicable regulatory agency", "The entity''s shareholders"]'::jsonb, 0, 'AU-C 580.09 requires the management representation letter to be addressed to the auditor. The letter is a communication from management to the engagement team, not to external parties such as regulators or shareholders. Unlike choice B, the representation letter is directed to the auditor, while communications to the board are addressed through separate governance channels.', 'easy', 1),

-- Q15: medium / L2 — Plans/intentions affecting carrying value
(1, 'Written Representations', 'During the 2025 audit of Summit Retail Group, the engagement partner at Chen & Price CPA identifies a long-term investment that management intends to hold to maturity, which affects its carrying value classification. The engagement partner ensures the representation letter addresses this matter. Under AU-C 580, when management''s intent or plan affects the carrying value of an asset, the representation should confirm:', '["That the auditor has approved management''s holding period for the investment", "Management''s intent or plan regarding the asset, as it affects the carrying value", "That the investment will generate a positive return over the holding period", "That the entity has sufficient liquidity to hold the investment indefinitely"]'::jsonb, 1, 'AU-C 580.A14 notes that when management''s intent or plans affect the carrying value of assets or liabilities, the auditor may request a specific representation confirming those intentions. The classification of held-to-maturity investments depends on management''s documented intent. Unlike choice A, the auditor does not approve management''s plans — the representation documents management''s stated intentions.', 'medium', 2),

-- Q16: easy / L1 — Period covered by representations
(1, 'Written Representations', 'What period do written representations in the management representation letter typically cover?', '["Only the fiscal quarter in which the audit report is issued", "All periods referred to in the auditor''s report", "The 12 months preceding the engagement letter date", "Only the most recent interim period reviewed by the auditor"]'::jsonb, 1, 'AU-C 580.14 states that written representations are for all periods referred to in the auditor''s report. When comparative financial statements are presented, the representations cover all periods presented in the financial statements. Unlike choice A, the representations are not limited to a single quarter — they encompass the full reporting period or periods addressed in the audit opinion.', 'easy', 1),

-- Q17: medium / L3 — Transactions lacking commercial substance
(1, 'Written Representations', 'During the 2025 audit of Oakridge Properties, the engagement team at Palmer & Vance discovers that the entity recorded a $4.5 million land swap with a related party at an inflated appraised value. The engagement partner considers what representation is needed regarding such transactions. Under AU-C 580, the representation letter should address transactions that:', '["Exceed a dollar threshold established by the audit committee", "Were entered into with government agencies or regulators", "May lack commercial substance or involve unusual terms that could affect the financial statements", "Have already been reviewed and approved by external legal counsel"]'::jsonb, 2, 'AU-C 580.11 and AU-C 550 require representations about related-party transactions and transactions that may lack commercial substance. The auditor should obtain representations confirming that all such transactions have been disclosed and properly recorded. Unlike choice A, the standard does not set a specific dollar threshold — the focus is on the nature and substance of the transaction rather than its size.', 'medium', 3),

-- Q18: easy / L2 — Off-balance-sheet arrangements representation
(1, 'Written Representations', 'The engagement team at Douglas & Rivera is completing the December 31, 2025 audit of Atlas Financial Services. The engagement partner considers whether the representation letter should address off-balance-sheet arrangements. Atlas has several variable interest entities. Under AU-C 580, management should represent that:', '["Off-balance-sheet arrangements are prohibited under the applicable financial reporting framework", "The auditor has independently verified all off-balance-sheet arrangements", "Off-balance-sheet arrangements have been eliminated from the entity''s structure", "All off-balance-sheet arrangements and their potential financial effects have been properly disclosed"]'::jsonb, 3, 'AU-C 580.11 and related disclosure requirements under ASC 825 require management to represent that all significant arrangements not recognized on the balance sheet have been disclosed. Variable interest entities are a common example requiring disclosure. Unlike choice A, off-balance-sheet arrangements are not prohibited — they must be properly disclosed when they exist.', 'easy', 2),

-- Q19: easy / L1 — Distinction between engagement letter and representation letter
(1, 'Written Representations', 'What is the primary difference between an engagement letter and a management representation letter?', '["The engagement letter is signed before the audit begins, while the representation letter is obtained near the end", "The engagement letter is signed by the auditor only, while the representation letter is signed by the audit committee", "The engagement letter addresses internal controls, while the representation letter addresses only financial data", "The engagement letter is optional, while the representation letter is discretionary"]'::jsonb, 0, 'AU-C 210 governs the engagement letter, which establishes the terms of the audit before work begins. AU-C 580 governs the management representation letter, obtained near the completion of fieldwork. Both documents are required, but they serve different purposes at different stages. Unlike choice D, neither document is optional — both are mandatory under professional standards.', 'easy', 1),

-- Q20: medium / L2 — Litigation and claims completeness representation
(1, 'Written Representations', 'During the 2025 audit of Redstone Chemical Corp., the engagement partner at Ashford & Young receives the management representation letter. The CFO has included a representation about pending litigation but omitted claims that have been asserted but for which no lawsuit has been filed. The engagement partner notes this omission. Under AU-C 580, the representation about litigation and claims should cover:', '["Only lawsuits in which the entity has been formally served with a complaint", "All known actual or possible litigation and claims whose effects should be considered in the financial statements", "Only litigation matters for which legal counsel has provided a loss estimate", "Lawsuits exceeding the materiality threshold established during audit planning"]'::jsonb, 1, 'AU-C 580.11 and AU-C 501 require management to represent the completeness of known actual or possible litigation and claims whose effects should be considered when preparing financial statements. This includes asserted and unasserted claims. Unlike choice A, the representation extends beyond formal lawsuits to encompass possible claims and unasserted matters of which management is aware.', 'medium', 2),

-- Q21: medium / L3 — Fair value measurement representations
(1, 'Written Representations', 'Cascade Analytics reports several Level 3 fair value measurements in its December 31, 2025 financial statements. The engagement team at Graham & Finley prepares the management representation letter and must determine what specific representations are needed for these measurements. Under AU-C 580 and AU-C 540, the representation about fair value measurements should address:', '["The reasonableness of the significant assumptions used, including whether they appropriately reflect management''s intent and ability to carry out specific courses of action", "The auditor''s concurrence with the valuation methodology selected by management", "A guarantee that market conditions will support the reported fair values for the foreseeable future", "Confirmation that only Level 1 inputs were used in all fair value measurements"]'::jsonb, 0, 'AU-C 580.11 and AU-C 540.A130 require management to represent the reasonableness of significant assumptions used in fair value measurements, including those related to intent and ability. Level 3 measurements rely heavily on unobservable inputs and judgment. Unlike choice D, the representation does not require that only Level 1 inputs be used — it addresses the reasonableness of whatever assumptions management employed.', 'medium', 3),

-- Q22: medium / L2 — Insurance coverage and claims representation
(1, 'Written Representations', 'The engagement team at Prescott & Hall is wrapping up the December 31, 2025 audit of Lakeside Hospitality Group. The entity experienced a fire at one property and filed a $2.7 million insurance claim. The engagement partner considers what representation is needed regarding insurance matters. Under AU-C 580, the representation letter should include management''s acknowledgment that:', '["The auditor has verified all insurance policies and claim amounts", "Insurance proceeds have already been received and deposited", "All pending or anticipated insurance claims and their expected recoveries have been disclosed to the auditor", "Insurance coverage limits exceed the total value of the entity''s assets"]'::jsonb, 2, 'AU-C 580.11 requires management to represent the completeness of information provided to the auditor, which includes disclosure of pending insurance claims and anticipated recoveries that could affect asset valuation. Undisclosed claims could create unrecognized contingent receivables. Unlike choice B, the representation concerns disclosure completeness, not confirmation that proceeds have been received.', 'medium', 2),

-- Q23: medium / L2 — Completeness of minutes of meetings
(1, 'Written Representations', 'During the 2025 audit of Trident Aerospace, the engagement team at Barrett & Sons requests the management representation letter. The board secretary asks why the letter includes a reference to corporate minutes. The engagement partner explains that under AU-C 580, the representation about minutes of meetings serves to:', '["Confirm that the auditor attended all board and committee meetings during the audit period", "Guarantee that no material decisions were made outside of formal board meetings", "Certify that board minutes comply with state corporate governance statutes", "Confirm that the minutes of all shareholders'' and directors'' meetings have been made available to the auditor"]'::jsonb, 3, 'AU-C 580.11 requires management to represent that the minutes of meetings of shareholders, directors, and relevant committees have been made available to the auditor. This ensures the auditor can identify authorized transactions and significant decisions. Unlike choice A, the auditor does not attend board meetings — the representation confirms that the written record of those meetings has been provided.', 'medium', 2),

-- Q24: medium / L3 — First-year audit representation considerations
(1, 'Written Representations', 'Mitchell & Ford CPA has been engaged to perform the first-year audit of Briarwood Technologies for the year ended December 31, 2025. The predecessor auditor issued an unmodified opinion on the prior year. The engagement partner at Mitchell & Ford prepares the representation letter and considers whether additional representations are needed for a first-year engagement. Under AU-C 510 and AU-C 580, the first-year representation letter should additionally address:', '["Whether the opening balances contain any misstatements that materially affect the current period''s financial statements", "Whether the predecessor auditor was independent during the prior-year engagement", "Whether the entity agrees to retain the predecessor auditor as a consultant", "Whether the prior-year audit was conducted under PCAOB standards"]'::jsonb, 0, 'AU-C 510.10 and AU-C 580 require the auditor in a first-year engagement to obtain representations about opening balances, including whether they contain misstatements that materially affect the current period. The incoming auditor did not observe prior-year closing procedures. Unlike choice B, management is not asked to represent the predecessor auditor''s independence — that is a matter between auditors.', 'medium', 3),

-- Q25: medium / L3 — Side agreements representation
(1, 'Written Representations', 'During the 2025 audit of Sterling Communications, the engagement team at Carver & Reed discovers that the entity has informal understandings with certain customers regarding extended payment terms not documented in the formal sales contracts. The engagement partner considers the representation letter implications. Under AU-C 580, the representation about side agreements should confirm that:', '["All customer contracts have been reviewed and approved by the entity''s legal department", "There are no side agreements, whether written or oral, that have not been disclosed to the auditor", "The entity will discontinue all informal arrangements by the next audit period", "Side agreements are immaterial and do not require disclosure under GAAP"]'::jsonb, 1, 'AU-C 580.11 requires management to represent the completeness of information provided, which includes undisclosed arrangements or side agreements. Side agreements — whether formal or informal — can affect revenue recognition timing and accounts receivable valuation. Unlike choice D, the auditor does not accept management''s materiality assessment of undisclosed arrangements at face value — all such agreements must be disclosed.', 'medium', 3),

-- Q26: easy / L1 — What constitutes "written" under AU-C 580
(1, 'Written Representations', 'Under AU-C 580, which of the following formats satisfies the requirement for a "written" representation?', '["A handshake agreement witnessed by the audit committee chair", "A signed letter on entity letterhead provided to the auditor", "An unsigned draft memorandum found in the client''s files", "A verbal statement made during the planning conference call"]'::jsonb, 1, 'AU-C 580.A2-A3 clarifies that a written representation takes the form of a representation letter addressed to the auditor, signed by appropriate members of management. A signed letter on entity letterhead satisfies this requirement. Unlike choice C, an unsigned draft does not constitute a formal representation because it lacks management''s affirmative acknowledgment and commitment.', 'easy', 1),

-- Q27: easy / L1 — Selection and application of accounting policies
(1, 'Written Representations', 'What accounting-related matter must management represent in the written representation letter under AU-C 580?', '["That the auditor selected the appropriate accounting framework for the entity", "That accounting policies have remained unchanged for at least five consecutive years", "That the selection and application of accounting policies are appropriate", "That the entity uses the same accounting policies as its industry peers"]'::jsonb, 2, 'AU-C 580.10 requires management to represent that the financial statements are prepared in accordance with the applicable financial reporting framework, including that the selection and application of accounting policies are appropriate. Unlike choice A, it is management — not the auditor — that is responsible for selecting appropriate accounting policies under the applicable framework.', 'easy', 1),

-- Q28: easy / L1 — Management responsibility statement in the letter
(1, 'Written Representations', 'What fundamental responsibility must management acknowledge in the written representation letter?', '["Responsibility for the preparation and fair presentation of the financial statements", "Responsibility for detecting all instances of employee fraud during the audit period", "Responsibility for the auditor''s assessment of internal control effectiveness", "Responsibility for selecting the audit firm and negotiating the audit fee"]'::jsonb, 0, 'AU-C 580.10 requires management to acknowledge its responsibility for the preparation and fair presentation of the financial statements in accordance with the applicable financial reporting framework. This is one of the most fundamental representations in the letter. Unlike choice C, the auditor''s assessment of internal controls is the auditor''s own responsibility, not management''s.', 'easy', 1),

-- Q29: hard / L4 — Evaluating representations when management tenure is limited
(1, 'Written Representations', 'During the 2025 audit of Horizon Logistics, the engagement partner at Taylor & Knox learns that the entity underwent significant management turnover. The current CEO joined in November 2025 and lacks knowledge of transactions from January through October. The CFO has been in the role for only six months. The engagement partner must evaluate the effect on the representation letter. Under AU-C 580, when current management was not present during all periods covered by the representations, the auditor should:', '["Exempt current management from signing the representation letter and rely on the prior management team''s oral statements", "Limit the audit opinion to only the period during which current management was present", "Still obtain the representation letter from current management, recognizing that the representations pertain to the financial statements rather than to personal knowledge of all transactions", "Postpone the audit until management has been in place for at least 12 months"]'::jsonb, 2, 'AU-C 580.A9 clarifies that written representations relate to the financial statements and the information provided to the auditor, not to each individual''s personal involvement in every transaction. Current management represents the financial statements as a whole regardless of their tenure. Unlike choice A, the auditor cannot exempt current management — written representations from the individuals currently responsible are always required.', 'hard', 4),

-- Q30: hard / L4 — Integrated audit representation differences under PCAOB
(1, 'Written Representations', 'Blackstone & Pryor serves as the auditor for an SEC registrant, conducting an integrated audit of Continental Aerospace''s financial statements and internal control over financial reporting for the year ended December 31, 2025. The engagement partner prepares the management representation letter covering both components of the integrated audit. Under PCAOB AS 2805 and AS 2201, in an integrated audit the representation letter must additionally address management''s:', '["Responsibility for establishing and maintaining effective internal control over financial reporting, including management''s assessment of internal control effectiveness", "Agreement that the auditor will not report any material weaknesses identified during the audit", "Guarantee that no significant deficiencies existed at any point during the reporting period", "Commitment to remediate all control deficiencies within 30 days of the report date"]'::jsonb, 0, 'PCAOB AS 2805 and AS 2201 require that in an integrated audit, the representation letter include management''s acknowledgment of its responsibility for establishing and maintaining effective internal control over financial reporting and its assessment of internal control effectiveness. Unlike choice C, management represents responsibility and assessment — not a guarantee that no deficiencies existed throughout the period.', 'hard', 4)
;

COMMIT;
